"use client"

import * as React from "react"
import { ChevronDown, Info } from "lucide-react"

import { cn } from "@/lib/utils"
import { formatNumber, type NumberFormat } from "@/registry/dashboardcn/lib/format"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import { TickBar } from "@/registry/dashboardcn/ui/tick-bar"

export interface DualMetricCardMetric {
  label: string
  value: number
  format?: NumberFormat
  currency?: string
  /** Bar fill from 0 to 100. Defaults to the metric's share of the total across all metrics. */
  progress?: number
  /** Show the metric's share of the total as a badge next to the value. */
  showShare?: boolean
  /** "ticks" draws a tick bar, "bar" a continuous bar. */
  meter?: "ticks" | "bar"
  /** Any CSS color. Defaults to chart-1 through chart-5 in order. */
  color?: string
  /** A supporting fact under the meter, e.g. { label: "Top source", value: "LinkedIn" }. */
  detail?: {
    label: string
    value: React.ReactNode
    /** Shown in a tooltip behind an info icon next to the label. */
    description?: string
  }
}

export interface DualMetricCardOption {
  value: string
  label: string
}

export interface DualMetricCardProps extends React.ComponentProps<typeof Card> {
  title: string
  /** Usually two metrics, shown side by side. */
  metrics: DualMetricCardMetric[]
  /** Options for the header dropdown. Omit to hide it. */
  options?: DualMetricCardOption[]
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  /** Number of ticks in each tick bar. */
  segments?: number
}

const defaultColors = [
  "var(--chart-1)",
  "var(--chart-2)",
  "var(--chart-3)",
  "var(--chart-4)",
  "var(--chart-5)",
]

/** A card with two metrics side by side, each with a value, share badge, meter, and a supporting fact. */
function DualMetricCard({
  title,
  metrics,
  options,
  value,
  defaultValue,
  onValueChange,
  segments = 30,
  className,
  ...props
}: DualMetricCardProps) {
  const [internal, setInternal] = React.useState(defaultValue ?? options?.[0]?.value ?? "")
  const selected = value ?? internal
  const selectedLabel = options?.find((option) => option.value === selected)?.label
  const total = metrics.reduce((acc, metric) => acc + metric.value, 0)

  return (
    <Card data-slot="dual-metric-card" className={cn("gap-0 py-0", className)} {...props}>
      <CardHeader className="flex items-center justify-between gap-3 border-b py-3 [.border-b]:pb-3">
        <CardTitle className="text-sm">{title}</CardTitle>
        {options?.length ? (
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="outline" size="sm">
                {selectedLabel}
                <ChevronDown className="text-muted-foreground" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end">
              <DropdownMenuRadioGroup
                value={selected}
                onValueChange={(next) => {
                  setInternal(next)
                  onValueChange?.(next)
                }}
              >
                {options.map((option) => (
                  <DropdownMenuRadioItem key={option.value} value={option.value}>
                    {option.label}
                  </DropdownMenuRadioItem>
                ))}
              </DropdownMenuRadioGroup>
            </DropdownMenuContent>
          </DropdownMenu>
        ) : null}
      </CardHeader>
      <CardContent className="@container py-5">
        <TooltipProvider>
          <div className="grid gap-6 @xs:grid-cols-2 @xs:gap-0 @xs:divide-x">
            {metrics.map((metric, index) => {
              const color = metric.color ?? defaultColors[index % defaultColors.length]
              const share = total ? metric.value / total : 0
              const fill = metric.progress ?? share * 100
              return (
                <div
                  key={metric.label}
                  data-slot="dual-metric"
                  className="flex min-w-0 flex-col gap-1 @xs:px-5 @xs:first:pl-0 @xs:last:pr-0"
                >
                  <div className="flex flex-wrap items-center gap-2">
                    <span className="text-3xl font-semibold tabular-nums tracking-tight">
                      {formatNumber(metric.value, { format: metric.format, currency: metric.currency })}
                    </span>
                    {metric.showShare ? (
                      <span
                        className="rounded-md px-1.5 py-0.5 text-xs font-medium tabular-nums"
                        style={{
                          color,
                          backgroundColor: `color-mix(in oklab, ${color} 15%, transparent)`,
                        }}
                      >
                        {formatNumber(share, { format: "percent", maximumFractionDigits: 2 })}
                      </span>
                    ) : null}
                  </div>
                  <span className="text-muted-foreground text-sm">{metric.label}</span>
                  <div className="mt-2 flex h-4 items-center">
                    {metric.meter === "bar" ? (
                      <div
                        role="progressbar"
                        aria-valuemin={0}
                        aria-valuemax={100}
                        aria-valuenow={Math.round(fill)}
                        className="bg-muted h-2 w-full overflow-hidden rounded-full"
                      >
                        <div
                          className="h-full rounded-full transition-[width]"
                          style={{ width: `${Math.min(100, Math.max(0, fill))}%`, backgroundColor: color }}
                        />
                      </div>
                    ) : (
                      <TickBar value={fill} segments={segments} color={color} className="h-4 gap-0.5" />
                    )}
                  </div>
                  {metric.detail ? (
                    <div className="mt-4 flex flex-col gap-0.5">
                      <span className="text-muted-foreground flex items-center gap-1 text-xs">
                        {metric.detail.label}
                        {metric.detail.description ? (
                          <Tooltip>
                            <TooltipTrigger asChild>
                              <button
                                type="button"
                                className="hover:text-foreground inline-flex rounded-full"
                              >
                                <Info className="size-3.5" />
                                <span className="sr-only">About {metric.detail.label}</span>
                              </button>
                            </TooltipTrigger>
                            <TooltipContent className="max-w-56">
                              {metric.detail.description}
                            </TooltipContent>
                          </Tooltip>
                        ) : null}
                      </span>
                      <span className="text-sm font-medium tabular-nums">{metric.detail.value}</span>
                    </div>
                  ) : null}
                </div>
              )
            })}
          </div>
        </TooltipProvider>
      </CardContent>
    </Card>
  )
}

export { DualMetricCard }

import * as React from "react"

import { cn } from "@/lib/utils"

export interface TickBarProps extends React.ComponentProps<"div"> {
  /** Current value, from 0 to max. */
  value: number
  max?: number
  /** Number of ticks. */
  segments?: number
  /** Any CSS color for the filled ticks. Defaults to chart-1. */
  color?: string
  /** Any CSS color for the unfilled ticks. Defaults to muted. */
  trackColor?: string
  /** "tick" draws thin bars; "pill" draws wide rounded ones. */
  shape?: "tick" | "pill"
}

/** A progress bar drawn as a row of ticks, lit up to the current value. */
function TickBar({
  value,
  max = 100,
  segments = 40,
  color = "var(--chart-1)",
  trackColor,
  shape = "tick",
  className,
  ...props
}: TickBarProps) {
  const fraction = Math.min(1, Math.max(0, value / (max || 1)))
  // Any non-zero value lights at least one tick so small values still register.
  const filled = fraction === 0 ? 0 : Math.max(1, Math.round(fraction * segments))

  return (
    <div
      data-slot="tick-bar"
      data-shape={shape}
      role="progressbar"
      aria-valuemin={0}
      aria-valuemax={max}
      aria-valuenow={value}
      className={cn(
        "flex w-full",
        shape === "tick" ? "h-6 gap-[3px]" : "h-4 gap-1.5",
        className
      )}
      {...props}
    >
      {Array.from({ length: segments }, (_, index) => {
        const lit = index < filled
        return (
          <span
            key={index}
            data-filled={lit}
            className={cn(
              "bg-muted h-full min-w-0 flex-1 transition-colors",
              shape === "tick" ? "rounded-[1.5px]" : "rounded-full"
            )}
            style={{ backgroundColor: lit ? color : trackColor }}
          />
        )
      })}
    </div>
  )
}

export { TickBar }

export type NumberFormat = "number" | "compact" | "currency" | "percent"

export interface FormatNumberOptions {
  format?: NumberFormat
  /** ISO 4217 code, used when format is "currency". Defaults to USD. */
  currency?: string
  locale?: string
  maximumFractionDigits?: number
}

const formatterCache = new Map<string, Intl.NumberFormat>()

function getFormatter(locale: string, options: Intl.NumberFormatOptions) {
  const key = locale + JSON.stringify(options)
  let formatter = formatterCache.get(key)
  if (!formatter) {
    formatter = new Intl.NumberFormat(locale, options)
    formatterCache.set(key, formatter)
  }
  return formatter
}

/**
 * Format a metric value for display.
 *
 * formatNumber(1234567)                          -> "1,234,567"
 * formatNumber(1234567, { format: "compact" })   -> "1.2M"
 * formatNumber(48.2, { format: "currency" })     -> "$48.20"
 * formatNumber(0.124, { format: "percent" })     -> "12.4%"
 */
export function formatNumber(
  value: number,
  {
    format = "number",
    currency = "USD",
    locale = "en-US",
    maximumFractionDigits,
  }: FormatNumberOptions = {}
): string {
  if (!Number.isFinite(value)) return "—"

  switch (format) {
    case "compact":
      return getFormatter(locale, {
        notation: "compact",
        maximumFractionDigits: maximumFractionDigits ?? 1,
      }).format(value)
    case "currency":
      return getFormatter(locale, {
        style: "currency",
        currency,
        maximumFractionDigits: maximumFractionDigits ?? 2,
      }).format(value)
    case "percent":
      return getFormatter(locale, {
        style: "percent",
        maximumFractionDigits: maximumFractionDigits ?? 1,
      }).format(value)
    default:
      return getFormatter(locale, {
        maximumFractionDigits: maximumFractionDigits ?? 0,
      }).format(value)
  }
}

/**
 * Format a fractional change as a signed percentage.
 *
 * formatDelta(0.124)  -> "+12.4%"
 * formatDelta(-0.03)  -> "-3.0%"
 * formatDelta(0)      -> "0.0%"
 */
export function formatDelta(delta: number, locale = "en-US"): string {
  if (!Number.isFinite(delta)) return "—"
  return getFormatter(locale, {
    style: "percent",
    signDisplay: "exceptZero",
    maximumFractionDigits: 1,
    minimumFractionDigits: 1,
  }).format(delta)
}

/**
 * Fractional change between two values. Returns 0 when there is no baseline.
 */
export function computeDelta(current: number, previous: number): number {
  if (!previous) return 0
  return (current - previous) / Math.abs(previous)
}
